import 'package:cephalopod/features/game/presentation/models/tutorial_right_button_ui.dart';
import 'package:cephalopod/features/game/presentation/models/tutorial_step_ui.dart';
import 'package:freezed_annotation/freezed_annotation.dart';

part 'how_to_play_view_state.freezed.dart';

/// Everything How to play shows: its [steps], one page each, the
/// [currentStep] on screen, counting from 0, and what the [rightButton]
/// under them does.
///
/// A UI model (docs/adr/0015): plain data generated by freezed
/// (docs/adr/0011).
@freezed
abstract class HowToPlayViewState with _$HowToPlayViewState {
  const factory HowToPlayViewState({
    required List<TutorialStepUi> steps,
    required int currentStep,
    required TutorialRightButtonUi rightButton,
  }) = _HowToPlayViewState;
}
